head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS20502.xml';
scwin.fn_SetPar;
scwin.vIsurCd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function() {
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(lbl_Isur);
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_FileIsurNm, arrPar[0].ISUR_NM);
    scwin.vIsurCd = arrPar[0].ISUR_CD;
};


/*************************
 * 함수명   : fn_SelectAttach
 * 설명     : 파일 추가
 * argument : object
 *************************/
scwin.fn_SelectAttach = function() {
    if (scwin.fn_InputCheck('Select') == false) return;
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.open();
    if (file.getValue() != "") {
        var vFile = file.getValue();
        var vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm != "") {
            if (scwin.fn_CheckExtension(vFileNm)) return; // 파일 확장자 체크
            dts_fileList.insertRow();
        } else {
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ISUR_CD", scwin.vIsurCd);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_NM", vFileNm);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_URL", file.getValue());
    }
};



/******************************
 * 함수명   : fn_CheckExtension
 * 설명     : 업로드 파일 확장자 체크 
 * argument : object
 *******************************/
scwin.fn_CheckExtension = function(fileNm) {
    var fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png"); // 허가 확장자 목록
    var vsFileNm = fileNm;
    var vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    var vsFlag = true;
    for (var i = 0; i < fileExts.length; i++) {
        if (fileExts[i] == vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};


/*********************************
 * 함수명   : fn_InputCheck
 * 설명     : 파일 업로드시 필수값 체크
 * argument : object
 *********************************/
scwin.fn_InputCheck = function(gubun) {
    if (scwin.vIsurCd == '') {
        $c.win.alert('발행기관을 입력하십시오.');
        txb_FileIsurNm.focus();
        return false;
    }
    if (gubun == 'Upload') {
        for (var i = 1; i <= dts_fileList.getTotalRow(); i++) {
            if (dts_fileList.getCellData(i, "FILE_TP_CD") == '') {
                $c.win.alert("[파일구분]을 선택하십시오.");
                return false;
            }
        }
        if (!$c.bns.checkGridMaxLength(dts_fileList, 'FILE_COMMENT', 100, '파일설명')) return false;
    }
    return true;
};


/*************************
 * 함수명   : fn_FileUpload
 * 설명     : 파일 업로드
 * argument : object
 *************************/
scwin.fn_FileUpload = function() {
    if (scwin.fn_InputCheck('Upload') == false) return; //필수값 체크

    var url = '/bns/FileFaxConn.do?method=uploadFile';
    url += '&SCREN_ID=' + scwin.vScrenID;
    url += '&SCREN_PROCES_TP_CD=' + SCREN_PROCS_TP_CD_03;
    url += '&FILE_FAX=' + 'FILE';
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pFile=dts_fileList)";
    trs_Save.Post();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(panel_Item);
    //파일 숨기기
    $c.stf.showObj(file, false);

    //호출파라미터설정
    scwin.fn_SetParam();
    //파일업로드 데이터셋 초기화

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.img_FileIsurNm_onclick = function() {
    scwin.fn_ShowIsur();
};
scwin.btn_lineadd_onclick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_Save_onclick = function() {
    scwin.fn_FileUpload();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = async function() {
    var arrPar = new Array();
    arrPar[0] = {
        FILE_UP: 'Y',
        ISUR_NM: $c.stf.getObjectValue(txb_FileIsurNm)
    };
    var parentFrame = $c.frame.path("../");
    scwin.fn_SetPar = parentFrame.fn_SetFileUpLoad;
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
